@startuml

class GasStation {
  + Id : int
  + Address : string
}

class FuelPump {
  + PumpNumber : int
  + SelfService : boolean
}

class Fuel {
  + Name : string
  + Octane : int
}

class DailyPrice {
  + Date : date
  + Price : double
}

class FuelPurchase {
  + Id : int
  + Liter : int
}

GasStation "1" -- "*" FuelPump
GasStation "1" -- "*" DailyPrice
FuelPump "*" -- "*" Fuel
FuelPump "1" -- "*" FuelPurchase
Fuel "1" -- "*" DailyPrice
DailyPrice "1" -- "*" FuelPurchase
FuelPurchase "*" -- "1" FuelPump

@enduml

